__disc("api/actor/1855612",{"cik":1855612,"name":"Grab Holdings Ltd","regime":"20-F/40-F","filings":[{"acc":"0001193125-21-348276","form":"20-F","date":"2021-12-06","url":"https://www.sec.gov/Archives/edgar/data/1855612/000119312521348276/d247862d20f.htm","rf_words":51419,"rf_ai":null,"rf_method":null,"txt":"04a1e01d193dd0e6","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001193125-22-125634","form":"20-F","date":"2022-04-28","url":"https://www.sec.gov/Archives/edgar/data/1855612/000119312522125634/d170219d20f.htm","rf_words":44922,"rf_ai":null,"rf_method":null,"txt":"5220dddcc3ad4063","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001193125-22-248003","form":"6-K","date":"2022-09-21","url":"https://www.sec.gov/Archives/edgar/data/1855612/000119312522248003/d392144d6k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"bc669f5cce10105d","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001193125-23-018197","form":"6-K","date":"2023-01-30","url":"https://www.sec.gov/Archives/edgar/data/1855612/000119312523018197/d378200d6k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"ae76f7ef9ea4bc4f","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0000950170-23-014551","form":"20-F","date":"2023-04-26","url":"https://www.sec.gov/Archives/edgar/data/1855612/000095017023014551/ck0001855612-20221231.htm","rf_words":44688,"rf_ai":null,"rf_method":null,"txt":"7340a6f6210b01e8","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0000950170-24-037611","form":"20-F","date":"2024-03-28","url":"https://www.sec.gov/Archives/edgar/data/1855612/000095017024037611/ck0001855612-20231231.htm","rf_words":44414,"rf_ai":null,"rf_method":null,"txt":"d79ef76f755dc4ff","coded":true,"n_ai_harm":2,"n_passages":4},{"acc":"0001855612-25-000013","form":"20-F","date":"2025-03-14","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561225000013/ck0001855612-20241231.htm","rf_words":39318,"rf_ai":null,"rf_method":null,"txt":"4de061fa50b4654d","coded":true,"n_ai_harm":3,"n_passages":5},{"acc":"0001855612-25-000026","form":"6-K","date":"2025-04-30","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561225000026/grab-20250331x6kfx3.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"f804b92e55896fce","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001855612-25-000024","form":"6-K","date":"2025-04-30","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561225000024/grab-20250331x6k.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"c497776b8f441649","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001855612-25-000058","form":"6-K","date":"2025-11-04","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561225000058/a6-kxearningsrelease1.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"a423d0b4090f7165","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001855612-25-000063","form":"6-K","date":"2025-11-10","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561225000063/a6-kxvaytransactionannounc.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"11c7eed232be6b73","coded":true,"n_ai_harm":0,"n_passages":4},{"acc":"0001855612-26-000009","form":"6-K","date":"2026-02-11","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000009/a6-kxsapphiretransactionan.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"c55188c9a7fdd2ec","coded":true,"n_ai_harm":0,"n_passages":5},{"acc":"0001855612-26-000020","form":"20-F","date":"2026-03-06","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000020/ck0001855612-20251231.htm","rf_words":30314,"rf_ai":null,"rf_method":null,"txt":"f19bcc52f56666be","coded":true,"n_ai_harm":6,"n_passages":11},{"acc":"0001855612-26-000051","form":"6-K","date":"2026-03-23","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000051/a6-kxgarnetannouncement.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"65a68e464d1d4065","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001855612-26-000077","form":"6-K","date":"2026-05-05","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000077/a6-kxearningsrelease3.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"ff51b0b866772314","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001855612-26-000123","form":"6-K","date":"2026-08-04","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000123/a6-kxearningsrelease2026q2.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"18f8d9c065c9e642","coded":true,"n_ai_harm":0,"n_passages":1},{"acc":"0001855612-26-000131","form":"6-K","date":"2026-08-13","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000131/ck0001855612-20260630.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"ac5427d3dd94a3e1","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001855612-26-000138","form":"6-K","date":"2026-09-15","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000138/a6-kforfx3sxatometransacti.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"3669ba9a1f48cb39","coded":true,"n_ai_harm":0,"n_passages":2},{"acc":"0001855612-26-000133","form":"6-K","date":"2026-09-15","url":"https://www.sec.gov/Archives/edgar/data/1855612/000185561226000133/a6-kxatometransactionannou.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"a0b86474c266dd83","coded":true,"n_ai_harm":0,"n_passages":4}],"passages":[{"id":"1855612-81d70aee91","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of Grab’s segments is subject to various regulations in each of the jurisdictions in which Grab operates. Focus areas of regulatory risk that Grab is exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) economic regulations such as price, supply regulation, safety, health, environment regulations, (vi) foreign ownership restrictions, (vii) artificial intelligence regulation and (viii) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. In addition, Grab may not be able to obtain all the licenses, permits and approvals that may be necessary to provide its offerings and those it plans to offer.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-21-348276"],"forms":{"20-F":1},"first":"2021-12-06","last":"2021-12-06","end":"2022-04-28"},{"id":"1855612-7b189bb8ee","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Grab’s internal systems and tools have a number of limitations, and Grab’s methodologies for tracking these metrics 87 Table of Contents may change over time, which could result in unexpected changes to Grab’s metrics, including the metrics Grab publicly discloses. If the internal systems and tools Grab uses to track these metrics undercount or overcount performance or contain algorithmic or other technical errors, the data Grab reports may not be accurate. While these numbers are based on what Grab believes to be reasonable estimates of its metrics for the applicable period of measurement, there are inherent challenges in measuring how the Grab platform is used.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-21-348276"],"forms":{"20-F":1},"first":"2021-12-06","last":"2021-12-06","end":"2022-04-28"},{"id":"1855612-989c69e316","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of our segments is subject to various regulations in each of the jurisdictions in which we operate. Focus areas of regulatory risk that we are exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) economic regulations such as price, supply regulation, safety, health and environment regulations, (vi) foreign ownership restrictions, (vii) artificial intelligence regulation and (viii) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. In addition, we may not be able to obtain all the licenses, permits and approvals that may be necessary to provide our offerings and those we plan to offer.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-22-125634"],"forms":{"20-F":1},"first":"2022-04-28","last":"2022-04-28","end":"2023-04-26"},{"id":"1855612-c7f7597fa2","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our internal systems and tools have a number of limitations, and our methodologies for tracking these metrics may change over time, which could result in unexpected changes to our metrics, including the metrics we publicly disclose. If the internal systems and tools we use to track these metrics undercount or overcount performance or contain algorithmic or other technical errors, the data we report may not be accurate. While these numbers are based on what we believe to be reasonable estimates of our metrics for the applicable period of measurement, there are inherent challenges in measuring how our platform is used.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-22-125634","0000950170-23-014551","0000950170-24-037611","0001855612-25-000013"],"forms":{"20-F":4},"first":"2022-04-28","last":"2025-03-14","end":"2026-03-06"},{"id":"1855612-ce5c05945e","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of our segments is subject to various regulations in each of the jurisdictions in which we operate. Focus areas of regulatory risk that we are exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) digital platform regulations, (vi) economic regulations such as price, supply regulation, safety, health and environment regulations, (vii) foreign ownership restrictions, (viii) artificial intelligence regulation and (ix) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. In addition, we may not be able to obtain all the licenses, permits and approvals that may be necessary to provide our offerings and those we plan to offer.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0000950170-23-014551"],"forms":{"20-F":1},"first":"2023-04-26","last":"2023-04-26","end":"2024-03-28"},{"id":"1855612-aa7e43badb","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of our segments is subject to various regulations in each of the jurisdictions in which we operate. Focus areas of regulatory risk that we are exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services (including digital bank) offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) digital platform regulations, (vi) economic regulations such as price, supply regulation, safety, health and environment regulations, (vii) foreign ownership restrictions, (viii) artificial intelligence regulation and (ix) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. In addition, we may not be able to obtain all the licenses, permits and approvals that may be necessary to provide our offerings and those we plan to offer.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0000950170-24-037611"],"forms":{"20-F":1},"first":"2024-03-28","last":"2024-03-28","end":"2025-03-14"},{"id":"1855612-048cc4906f","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Reputational","Economic/Property"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Any failure or malfunction of these processes could have a significant impact on the banks’ operations and their ability to serve their customers effectively, and could result in fines, sanctions, or other regulatory actions due to breaches of applicable laws and regulations. Furthermore, if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction, we may sustain financial, reputational or regulatory impacts. Our business is subject to laws that govern payment, financial services and banking activities and we may face challenges in obtaining and maintaining licenses and regulatory approvals and in maintaining relationships with regulators.","ev":{"mit:7.3":"if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction","harm:Reputational":"we may sustain financial, reputational or regulatory impacts","harm:Economic/Property":"we may sustain financial, reputational or regulatory impacts","layer:capability":"if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction","whose:own":"if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction","relation:within_purpose":"if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction"},"rev":null,"harm_quote":"if any artificial intelligence, statistical or machine learning models within our digital banks underperform or malfunction","status_quote":null,"reports":["0000950170-24-037611"],"forms":{"20-F":1},"first":"2024-03-28","last":"2024-03-28","end":"2025-03-14"},{"id":"1855612-119649f749","kind":"annual","source":null,"discloses":"ai_harm","mit":["4.3"],"primary":"4.3","status":"hypothetical","harm":["Economic/Property"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"digital bank customers","type":"Group of persons"}],"text":"Scam operations often involve large-scale set-ups akin to call centers, whose purpose is to convince victims to transfer funds or surrender their bank account credentials to the fraudsters. More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections. These novel defrauding tools and methods may result in large financial losses to our digital bank customers, which in turn may cause significant financial losses to our digital banks as the victim customers may have difficulty repaying their loans.","ev":{"mit:4.3":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections","harm:Economic/Property":"These novel defrauding tools and methods may result in large financial losses to our digital bank customers","layer:human_interaction":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections","whose:others":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections","relation:misuse":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections","misuse_by:third_party":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections"},"rev":null,"harm_quote":"More hi-tech fraudsters may employ phishing techniques and artificial intelligence, such as deepfakes of the victim's social connections","status_quote":null,"reports":["0000950170-24-037611","0001855612-25-000013"],"forms":{"20-F":2},"first":"2024-03-28","last":"2025-03-14","end":"2026-03-06"},{"id":"1855612-35737fcb1d","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of our segments is subject to various regulations in each of the jurisdictions in which we operate. Focus areas of regulatory risk that we are exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services (including digital bank) offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) digital platform regulations, (vi) economic regulations such as price, supply regulation, safety, health and environment regulations, (vii) foreign ownership restrictions, (viii) artificial intelligence regulation and (ix) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. Our business is subject to regulations from various regulators within each jurisdiction in which we operate, and such regulators may not always act in concert.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000013"],"forms":{"20-F":1},"first":"2025-03-14","last":"2025-03-14","end":"2026-03-06"},{"id":"1855612-28dbb07dfa","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Economic/Property","Reputational"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Any failure or malfunction of these processes could have a significant impact on the banks’ operations and their ability to serve their customers effectively, and could result in fines, sanctions, or other regulatory actions due to breaches of applicable laws and regulations. Furthermore, if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts. 23 Table of Contents Our business is subject to laws that govern payment, financial services, insurance and banking activities and we may face challenges in obtaining and maintaining licenses and regulatory approvals and in maintaining relationships with regulators. As we evolve our business, we may be subject to additional laws or requirements related to deposits, money transmission, lending, consumer protection, online payments, insurance distribution, captive insurance business and other financial regulation.","ev":{"mit:7.3":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","harm:Economic/Property":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","harm:Reputational":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","layer:capability":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","whose:own":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","relation:within_purpose":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts"},"rev":null,"harm_quote":"if any artificial intelligence, statistical or machine learning models within our digital banking or insurance business underperform or malfunction, we may sustain financial, reputational or regulatory impacts","status_quote":null,"reports":["0001855612-25-000013"],"forms":{"20-F":1},"first":"2025-03-14","last":"2025-03-14","end":"2026-03-06"},{"id":"1855612-85fd1a8cec","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3","3.1","1.1","2.1","7.4"],"primary":"7.3","status":"materialised","harm":["Human or fundamental rights","Reputational"],"layers":["capability"],"whose":["own","others"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"For example, our pricing model, including dynamic pricing, could be challenged or limited in emergencies and capped in certain jurisdictions or become the subject of litigation and regulatory inquiries. As a result, we may be forced to change our pricing model in certain jurisdictions and in certain circumstances, which could harm our revenue or result in a sub-optimal tax structure. 34 Table of Contents Our growing use of artificial intelligence and machine learning may present additional risks, including risks associated with algorithm development or use, the data sets used, and/or a complex, developing regulatory environment. Our growing use of AI (including machine learning) in our offerings presents additional risks. This technology presents a number of risks inherent in its use. AI algorithms or automated processing of data may be flawed and datasets may be insufficient or contain biased information, which can create inaccurate or discriminatory outcomes. AI algorithms may use third-party AI with unclear intellectual property rights or interests. Intellectual property ownership and license rights, including copyright, of generative and other AI output, have not been fully interpreted by courts or regulations. The United States and other countries may consider comprehensive legal compliance frameworks specifically for AI, which is a trend that may increase now that the European Commission has proposed the first such framework. Any failure or perceived failure by us to comply with such requirements could have an adverse impact on our business. AI use or management by us or others, including decisions based on automated processing or profiling, inappropriate or controversial data practices, or insufficient disclosures regarding machine learning and algorithms, have and could impair the acceptance of AI solutions or subject us to lawsuits, regulatory investigations or other harm, such as negative impacts to the value of our intellectual property or our brand. These and other deficiencies could also undermine the decisions, predictions or analysis AI applications produce, or lead to unintentional bias and discrimination, subjecting us to competitive harm, legal liability, and brand or reputational harm. The rapid evolution of AI may require us to allocate additional resources to help implement AI ethically in order to minimize unintended or harmful impacts, and may also require us to make additional investments in the development of proprietary datasets, machine learning models or other systems, which may be costly. Unfavorable media coverage could harm our business, financial condition, results of operations and prospects.","ev":{"status":"have and could impair the acceptance of AI solutions or subject us to lawsuits","mit:7.3":"AI algorithms or automated processing of data may be flawed and datasets may be insufficient or contain biased information","mit:3.1":"These and other deficiencies could also undermine the decisions, predictions or analysis AI applications produce","mit:1.1":"lead to unintentional bias and discrimination","mit:2.1":"inappropriate or controversial data practices","mit:7.4":"insufficient disclosures regarding machine learning and algorithms","harm:Human or fundamental rights":"which can create inaccurate or discriminatory outcomes","harm:Reputational":"subjecting us to competitive harm, legal liability, and brand or reputational harm","layer:capability":"AI algorithms or automated processing of data may be flawed and datasets may be insufficient or contain biased information","whose:own":"Our growing use of AI (including machine learning) in our offerings presents additional risks.","whose:others":"AI use or management by us or others","relation:within_purpose":"Our growing use of AI (including machine learning) in our offerings presents additional risks."},"rev":null,"harm_quote":"AI algorithms or automated processing of data may be flawed and datasets may be insufficient or contain biased information","status_quote":"have and could impair the acceptance of AI solutions or subject us to lawsuits","reports":["0001855612-25-000013"],"forms":{"20-F":1},"first":"2025-03-14","last":"2025-03-14","end":"2026-03-06"},{"id":"1855612-cf13a6e4cf","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"reduce incentives paid to driver-partners, merchant-partners and consumers; enhance and develop our superapp, the tools we provide the driver- and merchant-partners and payments network along with our other technology and infrastructure including AI; recruit and retain high quality industry talent;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-d20cfc762c","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Each of our segments is subject to numerous and often conflicting or evolving regulations from various regulators in each jurisdiction in which we operate. Focus areas of regulatory risk that we are exposed to include, among others: (i) evolution of laws and regulations applicable to deliveries, mobility and/or financial services (including digital bank) offerings, (ii) various forms of data regulation such as data privacy, data localization, data portability, cybersecurity and advertising or marketing, (iii) gig economy regulations, (iv) anti-trust regulations, (v) digital platform regulations, (vi) economic regulations such as price, supply regulation, safety, health and environment regulations, (vii) foreign ownership restrictions, (viii) AI regulation and (ix) regulations regarding the provision of online services, including with respect to the internet, mobile devices and e-commerce. Moreover, since we operate across eight countries, regulatory scrutiny or actions in one country may lead to other regulators taking similar actions in other countries.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-637caf9106","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We may also be required to disclose personal data to public agencies in the public interest or for policy formulation, which could put us at a disadvantage if the data is repurposed or lacks adequate protection. The increasing complexity of these laws, including evolving regulations around the use of data in AI and automated decision-making, may require significant compliance costs, limit how we use data, or result in penalties for non-compliance. For more information regarding these laws, see “Item 4.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-bf9de71de1","kind":"annual","source":null,"discloses":"ai_harm","mit":["1.1"],"primary":"1.1","status":"hypothetical","harm":["Human or fundamental rights"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Any misappropriation of personal information or perceived failure of our internal controls could harm our reputation and result in regulatory actions, significant fines, and lawsuits. While we generally obtain consents for data collection, any perceived lack of transparency regarding data use, algorithmic bias, or data transfers between our entities could expose us to compliance risks. While we invest significant resources to protect against these threats, we may be subject to liability, including significant remediation costs and legal fees, exceeding our insurance coverage.","ev":{"mit:1.1":"algorithmic bias","harm:Human or fundamental rights":"any perceived lack of transparency regarding data use, algorithmic bias, or data transfers between our entities could expose us to compliance risks","layer:capability":"any perceived lack of transparency regarding data use, algorithmic bias, or data transfers between our entities could expose us to compliance risks","whose:own":"any perceived lack of transparency regarding data use, algorithmic bias, or data transfers between our entities could expose us to compliance risks","relation:within_purpose":"any perceived lack of transparency regarding data use, algorithmic bias, or data transfers between our entities could expose us to compliance risks"},"rev":null,"harm_quote":"algorithmic bias","status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-1934afb6e7","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Economic/Property","Reputational"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"See “— Our lending business, including that of our digital banks, face credit risks.” Furthermore, as our digital banks and insurance business are in early stages, they are ramping up robust internal processes for daily operations, such as customer acquisition and service, product launches, internal reporting, risk management, and regulatory compliance. Given their novelty, these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions. 22 Table of Contents Our business is subject to evolving laws governing payments, banking, insurance and other financial services. We may face challenges in maintaining necessary licenses or adapting to additional regulatory requirements imposed on these services.","ev":{"mit:7.3":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","harm:Economic/Property":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","harm:Reputational":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","layer:capability":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","whose:own":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","relation:within_purpose":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions"},"rev":null,"harm_quote":"these processes or any underlying AI, statistical or machine learning models may malfunction, potentially resulting in operational underperformance, financial losses, reputational damage, or regulatory sanctions","status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-59389a4eef","kind":"annual","source":null,"discloses":"ai_harm","mit":["4.3"],"primary":"4.3","status":"elsewhere","harm":["Economic/Property"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"our digital bank customers","type":"Group of persons"}],"text":"Regarding our loan products, incorrect or fraudulent applicant information may lead to inaccurate credit decisions. Furthermore, sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia. These may result in large financial losses for our digital bank customers, which in turn may cause financial losses to our digital banks if customers cannot repay loans.","ev":{"status":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","mit:4.3":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","harm:Economic/Property":"These may result in large financial losses for our digital bank customers, which in turn may cause financial losses to our digital banks if customers cannot repay loans","layer:human_interaction":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","whose:others":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","relation:misuse":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","misuse_by:third_party":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia"},"rev":null,"harm_quote":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","status_quote":"sophisticated fraud methods, such as large-scale scam operations, phishing, and the use of AI or deepfakes, are a growing problem in Southeast Asia","reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-2a06a59e5b","kind":"annual","source":null,"discloses":"ai_harm","mit":["6.3"],"primary":"6.3","status":"hypothetical","harm":["Economic/Property"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"Additionally, competitors may independently develop equivalent or superior technology. As our business grows, competition increases and adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights, including risks arising from shared intellectual property within strategic alliances. Any such claims, regardless of merit, could result in expensive litigation, damage to our brand goodwill, or significant liability for damages.","ev":{"mit:6.3":"adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights","harm:Economic/Property":"Any such claims, regardless of merit, could result in expensive litigation, damage to our brand goodwill, or significant liability for damages.","layer:capability":"adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights","whose:own":"adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights","relation:within_purpose":"adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights"},"rev":null,"harm_quote":"adoption of AI deepens, we face a higher risk of receiving notices claiming we have infringed upon third-party rights","status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-bb701a990d","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For example, in 2022, we acquired a majority economic interest in Jaya Grocer. In 2025, we acquired a majority economic interest in Everrise, Validus Capital, a digital SME lending platform in Singapore, and Infermove, a Chinese AI robotics company. In early 2026, we agreed to acquire Stash Financial, Inc., a digital investing platform in the U.S.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-f2c7d27bfa","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3","3.1","1.1","2.1"],"primary":"7.3","status":"hypothetical","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"For example, our pricing model, including dynamic pricing, could be challenged or limited in emergencies and capped in certain jurisdictions or become the subject of litigation and regulatory inquiries. As a result, we may be forced to change our pricing model in certain jurisdictions, which could harm our revenue or result in a sub-optimal tax structure. 31 Table of Contents Our growing use of AI and machine learning may present additional risks, including risks associated with algorithm development or use, the data sets used, and/or a complex, developing regulatory environment. Our growing use of AI and machine learning in our offerings presents additional risks inherent in its use. AI algorithms or automated processing of data may be flawed and datasets may be insufficient or contain biased information, which can create inaccurate or discriminatory outcomes. These deficiencies could undermine the decisions, predictions, or analysis AI applications produce, subjecting us to competitive harm, legal liability, and reputational harm. Furthermore, AI algorithms may use third-party AI with unclear intellectual property rights, and the ownership of generative and other AI output has not been fully interpreted by courts or regulations. AI use or management by us or others, including decisions based on automated processing or profiling, inappropriate data practices or insufficient disclosures regarding AI and machine learning, could subject us to lawsuits, regulatory investigations, or negative impacts to the value of our intellectual property. Additionally, the countries in which we operate may consider comprehensive legal compliance frameworks for AI, similar to those established by the European Commission. In Vietnam, the National Assembly passed the Law on Artificial Intelligence, which will come into effect in March 2026. Any actual or perceived failure to comply could have an adverse impact on our business. The rapid evolution of AI may also require us to allocate additional resources to implement AI ethically and make costly investments in proprietary datasets and machine learning models. Unfavorable media coverage could harm our business, financial condition, results of operations and prospects.","ev":{"mit:7.3":"AI algorithms or automated processing of data may be flawed","mit:3.1":"These deficiencies could undermine the decisions, predictions, or analysis AI applications produce","mit:1.1":"datasets may be insufficient or contain biased information, which can create inaccurate or discriminatory outcomes","mit:2.1":"inappropriate data practices or insufficient disclosures regarding AI and machine learning","harm:Human or fundamental rights":"datasets may be insufficient or contain biased information, which can create inaccurate or discriminatory outcomes","harm:Economic/Property":"negative impacts to the value of our intellectual property","harm:Reputational":"subjecting us to competitive harm, legal liability, and reputational harm","layer:capability":"AI algorithms or automated processing of data may be flawed","whose:own":"Our growing use of AI and machine learning in our offerings presents additional risks inherent in its use.","relation:within_purpose":"Our growing use of AI and machine learning in our offerings presents additional risks inherent in its use."},"rev":null,"harm_quote":"AI algorithms or automated processing of data may be flawed","status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-5279913375","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our internal systems and tools have inherent limitations, and our tracking methodologies may change over time, which could result in unexpected changes to our metrics. If these systems and tools undercount or overcount performance, or contain algorithmic or technical errors, the data we report may be inaccurate. Furthermore, the accuracy of our metrics is subject to inherent challenges, such as fraudulent activity or consumers maintaining multiple accounts in violation of our Terms of Service.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null},{"id":"1855612-35aa83af0a","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Physical (injury)","Economic/Property"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"To mitigate these risks, we work with governments to drive cashless penetration and provide consumer incentives, such as GrabPay rewards and vouchers, to discourage cash use. Any failure in collection, enforcement, or regulatory compliance could materially harm our business, financial condition, results of operations and prospects. 37 Table of Contents Our investments in autonomous vehicle (“AV”) technologies may not be successful. We have invested in and partnered with third parties to explore the deployment of AV technologies in Southeast Asia. The AV industry is in its early stages in Southeast Asia. If our competitors, whether current or new to the region, deploy functional or advanced AV technologies before we do, or if their technologies are perceived as safer or more efficient, our competitive position could be significantly undermined. Furthermore, any failures or accidents involving AVs on our platform, or high-profile incidents involving us or our partners, could result in substantial legal liability and harm our reputation. The regulatory landscape for AVs in Southeast Asia remains fragmented and is evolving at different rates across the countries in which we operate. We may face inconsistent or restrictive regulations regarding AV testing, licensing, and data security.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000020"],"forms":{"20-F":1},"first":"2026-03-06","last":"2026-03-06","end":null}],"k8":[{"id":"1855612-6k-8d91d19d98","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"He led over 1,000 engineers, data scientists and technical program managers across various countries to design, build and optimise large-scale systems powering Grab’s biggest verticals. Under his leadership, his team created a unified tech platform to enable teams to use technical features across different lines of business for faster innovation, and drove widespread adoption of artificial intelligence and automation for faster response to dynamic market conditions. Suthen is based in Singapore, Grab’s regional headquarters, and will continue to report directly to co-founder Tan Hooi Ling. He will oversee Grab’s global network of eight Research and Development (R&D) Centres, which draws talent from around the world to create impactful solutions for Southeast Asia. From using artificial intelligence to create accurate hyperlocal maps for improved driver navigation, to self-serve advertising solutions for merchants to boost their in-app visibility, Grab’s technology teams continue to develop impactful features that not only bring greater convenience to consumers, but also support partners to grow in Southeast Asia’s rising digital economy. ### About Grab Grab is a leading superapp in Southeast Asia. Grab operates across the deliveries, mobility and digital financial services sectors in over 480 cities in eight countries in Southeast Asia, including Cambodia, Indonesia, Malaysia, Myanmar, the Philippines, Singapore, Thailand and Vietnam.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-22-248003"],"forms":{"6-K":1},"first":"2022-09-21","last":"2022-09-21","end":null},{"id":"1855612-6k-26afe93dcb","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"An entrepreneur for the early part of his career, Philipp co-founded and was the CTO of Skobbler, which was acquired by Silicon Valley based Telenav, where he served as Senior VP for Engineering in his last role prior to joining Grab. At Telenav, Philipp was a part of the executive team, leading the global engineering team of 400+ members and focused on innovation in the connected car space, delivering solutions to tens of millions of vehicles as well as AI based mapmaking. About Grab: Grab is Southeast Asia’s leading superapp based on GMV in 2021 in each of food deliveries, mobility and the e-wallets segment of financial services, according to Euromonitor.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001193125-23-018197"],"forms":{"6-K":1},"first":"2023-01-30","last":"2023-01-30","end":null},{"id":"1855612-6k-56a82b0eeb","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Operating Cash Flow of $936 million and Adjusted Free Cash Flow of $157 million on a trailing 12-month basis SINGAPORE, April 30, 2025 - Grab Holdings Limited (NASDAQ: GRAB) today announced unaudited financial results for the first quarter ended March 31, 2025. \"We had a strong set of results to start the year, sustaining robust demand growth momentum to achieve yet another quarterly record number of users on our platform, even amid the seasonal demand impacts from the Lunar New Year and Ramadan fasting period. We also grew the number of active partners on our platform, and now have more active driver- and merchant-partners than ever before,\" said Anthony Tan, Group Chief Executive Officer and Co-Founder of Grab. \"While we are cognizant that there are increased levels of uncertainty in the global macroeconomic landscape, we will continue to harness AI and our technological capabilities to improve the reliability and affordability of our offerings. This will increasingly position us as a counter-cyclical company that can weather through uncertainties in the macroeconomic landscape.\" “We continued to drive profitable growth across the business, with Grab achieving another quarter of record revenues, our thirteenth consecutive quarter of Adjusted EBITDA expansion, and Adjusted Free Cash Flow scaling to $157 million on a trailing 12-months basis,” said Peter Oey, Chief Financial Officer of Grab. “Looking ahead to the second quarter, we expect to drive strong, sequential On-Demand GMV and overall revenue growth, while remaining disciplined on costs as a company.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000024"],"forms":{"6-K":1},"first":"2025-04-30","last":"2025-04-30","end":null},{"id":"1855612-6k-6ac253e151","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Additionally, we plan to launch a fully green GrabCab fleet, featuring low- and zero-emission hybrid and electric vehicles. In March 2025, we announced the signing of new Memoranda of Understanding (MoUs) with four autonomous technology companies: Autonomous A2Z, Motional, WeRide and Zelos. These partnerships aim to explore the impact and potential role of autonomous vehicles within Southeast Asia’s transportation landscape. ———————————— 8 Surged Mobility rides are defined as completed rides where demand exceeds supply in a specified region and/or where pricing regulations adherence is required. Financial Services ($ in millions, unless otherwise stated) Q1 2025 Q1 2024 YoY % Change YoY % Change (unaudited) (unaudited) (constant currency) Operating metrics: Loan portfolio 566 363 56% Financial measures: Revenue 75 55 36% 38% Segment Adjusted EBITDA (30) (28) (9)%","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000024","0001855612-25-000026"],"forms":{"6-K":2},"first":"2025-04-30","last":"2025-04-30","end":null},{"id":"1855612-6k-e3dad442ef","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Adjusted Free Cash Flow of $283 million on a trailing twelve months basis SINGAPORE, November 4, 2025 - Grab Holdings Limited (NASDAQ: GRAB) today announced unaudited financial results for the third quarter ended September 30, 2025. “This quarter marks another vital step forward in our journey, not just in financial performance, but in how we are building a more resilient, technology-driven platform for the long term. Grab’s growth engine continues to gain momentum, with On-Demand GMV accelerating to 24% year-over-year (“YoY”), or 20% YoY on a constant currency basis1, while achieving our fifteenth consecutive quarter of Adjusted EBITDA growth,” said Anthony Tan, Group Chief Executive Officer and Co-Founder of Grab. \"Looking ahead, we will continue to prioritize innovation to fuel profitable growth in our core On-Demand business, while making disciplined investments to accelerate growth in Financial Services and explore Autonomous Vehicle (“AV\") and Remote Driving opportunities.” “We continued to accelerate growth while delivering sequential Adjusted EBITDA margin improvements and Adjusted Free Cash Flow generation,” said Peter Oey, Chief Financial Officer of Grab. “This quarter’s results underscore the resilience of our counter-cyclical business model and is a testament to the strong execution of our ecosystem partners and our employees. We now expect full-year Group revenue to come in at $3.38 to $3.40 billion from our prior range of $3.33 to $3.40 billion, and are also upgrading our full-year Adjusted EBITDA guidance to $490 million to $500 million from $460 million to $480 million.” 1 We calculate constant currency by translating our current period financial results using the corresponding prior period’s monthly exchange rates for our transacted currencies other than the U.S. dollar.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000058"],"forms":{"6-K":1},"first":"2025-11-04","last":"2025-11-04","end":null},{"id":"1855612-6k-914cfafd4f","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Other Events During the quarter, we announced plans to launch Autonomously Intelligent Ride (“Ai.R”), our first AV service for consumers in Singapore, in partnership with WeRide. By early 2026, Ai.R is expected to start taking its first batch of passengers, improving access to key amenities including supermarkets, schools and major transport nodes. In October, we announced our multi-year partnership with May Mobility to integrate their autonomous driving technology, including fleet management, vehicle matching and routing systems, into our core ecosystem. The partnership will combine May Mobility’s operational best practices and Grab’s local expertise to facilitate the safe and reliable implementation of AVs into Southeast Asia, tailored to the unique needs of local infrastructure.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000058"],"forms":{"6-K":1},"first":"2025-11-04","last":"2025-11-04","end":null},{"id":"1855612-6k-e7090e6557","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Upon Closing, Grab will hold a minority equity interest in Vay. Anthony Tan, Chief Executive Officer and Co-founder of Grab, said, “We believe the future of mobility in Southeast Asia will be a hybrid model that relies on the expertise of our driver-partners alongside autonomous vehicles and remote driving services. This initial investment will help accelerate Vay’s remote driving technology development and create valuable technical and operational synergies for Grab’s long-term mobility strategy. It will also support Vay’s expansion in the U.S., where they serve a growing segment of consumers who prefer not to be car owners and are looking for more flexible, affordable, mobility options.” Thomas von der Ohe, Chief Executive Officer and Co-Founder of Vay, said, “As we plan to deploy tens of thousands of shared, electric, driverless vehicles over the coming years, we couldn't be more excited to have one of the best operators in the world join us on this journey. Mr.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000063"],"forms":{"6-K":1},"first":"2025-11-10","last":"2025-11-10","end":null},{"id":"1855612-6k-f8e2b0e918","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Grab will leverage its marketing, product development, fleet management, and go-to-market expertise to support Vay’s growth in the U.S., while exploring how Vay’s service model can complement Grab’s suite of mobility services in Southeast Asia. In addition, this investment supports Grab’s autonomous mobility strategy. For example, the driving data that Vay collects through its fleet could accelerate the training of AI models that improve autonomous vehicles’ perception of the real world. Grab’s announcement today follows recent investments in autonomous driving players, including WeRide and May Mobility. Patrick Pichette, investor and former CFO of Google: “I have backed Vay for years, and I am even more excited to see what its proven technology and product can achieve now that it is paired with Grab’s operational excellence. Vay’s focus on the driverless rental car space, a complement to robotaxis, offers its own unique massive market opportunity, and a long-term opportunity to replace private car ownership.” Vay launched its remote-driven commercial fleet in Las Vegas in 2024. Built to enable human-machine collaboration, Vay’s technology is designed to navigate complex, high-density environments, such as the Las Vegas Strip, one of the areas where Vay currently operates.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000063"],"forms":{"6-K":1},"first":"2025-11-10","last":"2025-11-10","end":null},{"id":"1855612-6k-4daa20e6f6","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Its automotive-grade remote driving technology prioritizes high safety standards and low-latency connectivity and has been certified by German vehicle safety and motor transport authorities to rigorous automotive standards. Vay intends to add autonomous driving functionalities into its system based on its high-quality remote driving data. Its team consists of experts from autonomous and automotive industry companies, and its investors include Kinnevik, Coatue, Atomico, General Catalyst, and Eurazeo.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000063"],"forms":{"6-K":1},"first":"2025-11-10","last":"2025-11-10","end":null},{"id":"1855612-6k-3c77e7ffb1","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Since its launch, users have taken tens of thousands of rides and can hail a Vay car at a wide variety of locations throughout Las Vegas, including the busiest hotels on the Strip. Vay intends to add autonomous driving functionalities into its system based on its high-quality remote driving data. Vay has recently expanded its offering to include B2B services, enabling remote driving for private cars, trucks, vans, and autonomous vehicles, among others. Founded in Berlin in 2018 by Thomas von der Ohe, Fabrizio Scelsi, and Bogdan Djukic, the team of over 150 people combines the best of two worlds - software from Silicon Valley and automotive engineering from Europe.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-25-000063"],"forms":{"6-K":1},"first":"2025-11-10","last":"2025-11-10","end":null},{"id":"1855612-6k-be9b615b37","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 projectsapphire_pressrelea.htm EX-99.1 Exhibit 99.1 Grab Accelerates Financial Services Roadmap with Acquisition of Digital Investing Platform, Stash Financial, Inc. Grab is expanding its international Financial Services footprint and accelerating entry into the mass-market investing segment by acquiring Stash, an AI-powered investing app. Acquiring Stash offers Grab access to talent and technology to accelerate its Financial Services roadmap, as well as high-margin subscription-based revenue.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000009"],"forms":{"6-K":1},"first":"2026-02-11","last":"2026-02-11","end":null},{"id":"1855612-6k-fab09145ae","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Anthony Tan, Group Chief Executive Officer and Co-Founder of Grab, said: “This is a milestone in Grab’s evolution as a trusted international provider of financial services. This acquisition brings more than just recurring, high-margin subscription revenue; we will strengthen Grab’s fintech knowhow with Stash’s AI-powered investing app, designed with existing U.S. regulatory requirements at its core. While we remain operationally focused on Southeast Asia and scaling our regional loanbook, this move reinforces our mission of democratizing financial services for everyone.” Brandon Krieg, Co-Founder and Co-CEO of Stash, said: “Ed and I founded Stash because we believe the tools and advice to build long-term wealth should be accessible to everyone, not just the top 1%.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000009"],"forms":{"6-K":1},"first":"2026-02-11","last":"2026-02-11","end":null},{"id":"1855612-6k-7d746e2981","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Grab has a track record of ecosystem-building through harnessing user data and a culture of entrepreneurship that will serve our growth ambitions. This acquisition gives us the best of both worlds: the capabilities to double down on growth in the U.S., and the resources of a technology powerhouse to accelerate our vision of personalized, AI-driven financial guidance for millions of people across all parts of their financial lives.” Regulated by the SEC, Stash is a U.S. registered investment advisor with more than $5 billion in assets under management. Through its subscription-based app, Stash serves over one million consumers with accessible investing, banking, and financial education tools designed to support long-term financial decision-making.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000009"],"forms":{"6-K":1},"first":"2026-02-11","last":"2026-02-11","end":null},{"id":"1855612-6k-67c998a7b1","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"A core part of Stash's platform is its use of technology to deliver personalized financial guidance at scale. This includes AI Money Coach, which serves as a financial companion offering guidance and execution tailored and adaptable to users’ life goals and financial circumstances. It is built for regulated financial services and combines expert knowledge, deep financial integrations, compliance-by-design, and direct actionability across Stash’s investing, banking, and saving products. Interactions with AI Money Coach are auditable and configurable through defined policies and controls. This enables Stash to deploy AI responsibly at scale while maintaining high standards of consumer protection and regulatory integrity. AI Money Coach has driven strong engagement since its launch in late 2024, with approximately one in two users taking a positive financial action on the same day, up nearly 40% in 2025. Following the acquisition, Grab plans to support Stash's continued growth in the U.S. consumer market, while exploring opportunities to introduce Stash's investing solutions, including AI Money Coach, in Southeast Asia longer-term. Based on current business momentum and the execution of the company’s strategic plan, Stash is expected to generate more than $60 million in Adjusted EBITDA in the 2028 calendar year.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000009"],"forms":{"6-K":1},"first":"2026-02-11","last":"2026-02-11","end":null},{"id":"1855612-6k-0164b2d8b9","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The platform combines financial education with personalized guidance to help customers make informed financial decisions. Powered by AI Money Coach, Stash delivers personalized financial guidance at scale, turning complex financial topics into clear recommendations that help customers understand what to do next. Stash offers a broad suite of products designed to support different financial needs.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000009"],"forms":{"6-K":1},"first":"2026-02-11","last":"2026-02-11","end":null},{"id":"1855612-6k-7129967818","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For us, success starts with the community - we will be on the ground to listen first-hand to user needs. We are here to be a long-term partner to Taiwan, and look forward to providing our AI-enabled products to help local merchants and delivery-partners grow with the digital AI economy,” Tan added. After the acquisition, Grab will have a presence across 21 cities in Taiwan. This deal combines Grab’s AI-enabled products and deep operational expertise with foodpanda’s extensive coverage across Taiwan. The foodpanda business generated approximately US$1.8 billion in Gross Merchandise Value (GMV) and is profitable on an adjusted EBITDA basis (before the allocation of Delivery Hero’s group costs) in 20251.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000051"],"forms":{"6-K":1},"first":"2026-03-23","last":"2026-03-23","end":null},{"id":"1855612-6k-8be644d9bc","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Grab aims to similarly contribute to Taiwan’s economy by providing flexible earning opportunities for millions of people and small businesses, in line with local regulations. Grab will bring its AI product suite to Taiwan, leveraging the same technology that currently serves over 50 million monthly transacting users across more than 900 cities. This includes GrabMaps, Grab’s proprietary hyperlocal mapping technology, that uses real-time route planning and predictive food preparation times to make every delivery more reliable and efficient. For consumers, Grab aims to bring a smarter way to eat to Taiwan, using AI to offer more personalised restaurant recommendations and a wider selection of cuisines. For merchants, Grab will provide digital tools and data insights to help them reach a wider customer base. This includes access to an AI Merchant Assistant, real-time sales analytics, and marketing manager tools. For delivery-partners, Grab will offer a safe and flexible way to earn an income, with insurance coverage, in-app safety features, and tools that help them maximise their earnings.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000051"],"forms":{"6-K":1},"first":"2026-03-23","last":"2026-03-23","end":null},{"id":"1855612-6k-99d8966e67","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Typically the first quarter is our seasonally softest quarter, however our On-Demand GMV growth accelerated to 24% year-over-year (\"YoY”), or 21% YoY on a constant currency basis2, marking another quarter of record profitability. Our results demonstrate the resilience of our platform, especially as Southeast Asia navigates an uncertain macroeconomic environment from the fuel crisis,\" said Anthony Tan, Group Chief Executive Officer and Co-Founder of Grab. “As we look ahead to the rest of the year, we remain committed to delivering durable, profitable growth while standing shoulder-to-shoulder with our communities — leaning deeply into AI to outserve our users with hyper-personalized experiences, while simultaneously unlocking more sustainable earnings opportunities for our ecosystem partners.\" \"Our first quarter performance highlights our consistent execution and the growing operating leverage across our platform, with Adjusted EBITDA growing 46% YoY to a record $154 million. This strong start keeps us firmly on track to deliver our 2026 Revenue guidance of $4.04 billion to $4.10 billion and Adjusted EBITDA guidance of $700 million to $720 million,\" said Peter Oey, Chief Financial Officer of Grab. \"With trailing Twelve Month Adjusted Free Cash Flow expanding to $489 million in the first quarter, we remain focused on disciplined capital allocation to drive profitable growth and maintain our commitment to return capital to shareholders.\" 1 These are non-IFRS measures.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000077"],"forms":{"6-K":1},"first":"2026-05-05","last":"2026-05-05","end":null},{"id":"1855612-6k-255a31e815","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Adjusted Free Cash Flow1 of $450 million on a trailing twelve months basis SINGAPORE, August 4, 2026 - Grab Holdings Limited (NASDAQ: GRAB) today announced unaudited financial results for the second quarter ended June 30, 2026. \"We delivered another strong quarter. We executed against our product and AI-led strategy with On-Demand GMV growth accelerating to 22% year-over-year (“YoY”) on a constant currency basis2, and we reached a record 54 million Monthly Transacting Users,\" said Anthony Tan, Group Chief Executive Officer and Co-Founder of Grab. “Our Grab intelligence layer is now embedded across every layer of our platform, lifting driver and merchant-partner earnings, while improving our operating efficiency. We expect this intelligence layer to further strengthen as it scales, translating directly into deeper user engagement, and durable, profitable growth for Grab.\" \"Adjusted EBITDA margin expanded to 16.9% of Group revenue from 13.3% a year ago, marking our eighteenth straight quarter of Adjusted EBITDA growth and proving that our business model scales,\" said Peter Oey, Chief Financial Officer of Grab. \"We are raising our full-year 2026 guidance to $4.10 billion to $4.15 billion in Group revenue and $720 million to $740 million in Adjusted EBITDA, reflecting the strength of our underlying business alongside the consolidation of Superbank and the acquisition of Stash.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000123"],"forms":{"6-K":1},"first":"2026-08-04","last":"2026-08-04","end":null},{"id":"1855612-6k-b9876bf31a","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The increase was primarily due to a $25 million increase in media costs and agency marketing costs for marketing campaigns. 7 General and administrative expenses (in $ millions, unless otherwise stated) Six Months Ended June 30, 1H2025-1H2026 2026 2025 % Change General and administrative expenses 265 232 14 % Percentage of revenue 14 % 15 % General and administrative expenses increased by $33 million, or 14%, to $265 million for the six months ended June 30, 2026 from $232 million for the six months ended June 30, 2025. The increase was primarily due to (i) an $18 million increase in staff costs, driven by higher share-based compensation costs and increases in salaries and bonuses; (ii) an $8 million increase in software subscription costs driven by our continued push to adopt more Artificial Intelligence (AI)-powered platforms and tools to support engineering and productivity; (iii) a $6 million increase in withholding tax relating to royalty fees; and (iv) a $3 million increase in research fees related to user behavior insights and competitive analysis. These increases were partially offset by a $7 million decrease in professional, consultancy and legal fees based on the timing and pacing of projects year over year, and a $4 million decrease in penalties as a result of the reversal of a legal provision.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000131"],"forms":{"6-K":1},"first":"2026-08-13","last":"2026-08-13","end":null},{"id":"1855612-6k-98d7a363d8","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Others Multiple operating business activities that are not individually material. They include mapping services, autonomous vehicle services and last-mile delivery infrastructure. ii)Information about reportable segments The CODM evaluates operating segments based on revenue and Segment Adjusted EBITDA. Segment reporting revenue is disclosed in Note 8.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000131"],"forms":{"6-K":1},"first":"2026-08-13","last":"2026-08-13","end":null},{"id":"1855612-6k-722ccf9ddf","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Proposed transaction covers five markets and accelerates Grab's growth and penetration into consumer lending, while unlocking new distribution channels for Atome Financial and cross-sell opportunities for both ecosystems Combining Atome Financial’s AI-powered lending infrastructure with Grab’s ecosystem insights widens financial access for underserved consumers and merchants across Southeast Asia, while enabling Grab to scale consumer lending with disciplined credit risk management Grab expects Financial Services Segment Adjusted EBITDA1 of $500 million and a gross loan portfolio of over $6 billion by 2028, including Atome Financial","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000133"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null},{"id":"1855612-6k-18076c76c6","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Through Atome Financial, Grab would be able to access a scaled and proven platform for consumer lending. For Atome Financial, access to Grab’s ecosystem gives the company new distribution opportunities across the region. “Atome Financial’s leading use of AI to underwrite digital lending to millions of users across the region, while managing risk effectively, will help to scale and strengthen Grab’s whole ecosystem. The proposed transaction accelerates the growth and profitability of our financial services segment by deepening our consumer lending capabilities and unlocking opportunities for us to serve Atome’s large merchant network.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000133"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null},{"id":"1855612-6k-6f6df68baf","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Over eight years, we've built a sustainable and reliable financial services platform serving millions of customers across five markets. Powered by AI and data, every transaction makes our underwriting smarter and our products more personalised. With Grab's ecosystem, and our proven AI-powered lending infrastructure, we can extend that to millions more across Southeast Asia who've been left out — and together, do more to close the financial inclusion gap than either of us could alone.\" 3 Atome Financial has a minority stake in a joint venture in Thailand. 4 Based on Atome’s management accounts, which have not been reviewed or audited. 2 Complementary Capabilities and Vision Access to credit remains an important driver of economic opportunity in Southeast Asia, where more than 70%5 of adults are unbanked or underbanked. The proposed transaction would leverage three strategic pillars to expand access to credit solutions that are transparent, responsible, and built for how the region borrows. 1.Highly complementary regional footprint and product suite: Both companies operate across Singapore, Malaysia, the Philippines, Indonesia and Thailand, with minimal product overlap.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000133"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null},{"id":"1855612-6k-fff243481c","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Combining these strengths means greater access to flexible payment options for Grab's ecosystem of nearly 54 million Monthly Transacting Users, and more cross-sell opportunities for Grab into Atome Financial’s network of over 30,000 brands. 2.Enhancing credit capabilities to drive scale: The proposed acquisition mutually strengthens the companies’ credit underwriting capabilities, and is expected to be a meaningful contributor to Grab’s Financial Services segment targets. Pairing Atome Financial’s AI-powered lending infrastructure with Grab’s ecosystem insights could significantly enhance Grab’s credit risk underwriting capabilities, allowing Grab to expand product accessibility, while helping to prevent consumer over-indebtedness. This is expected to translate into faster loan book growth and lower cost-to-serve than either company scaling independently.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000133"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null},{"id":"1855612-6k-7d1139476b","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Proposed transaction covers five markets and accelerates Grab's growth and penetration into consumer lending, while unlocking new distribution channels for Atome Financial and cross-sell opportunities for both ecosystems Combining Atome Financial’s AI-powered lending infrastructure with Grab’s ecosystem insights widens financial access for underserved consumers and merchants across Southeast Asia, while enabling Grab to scale consumer lending with disciplined credit risk management SINGAPORE, September 15, 2026 — Grab Holdings Limited (NASDAQ: GRAB) (“Grab”) and Neuroncredit Pte. Ltd.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000138"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null},{"id":"1855612-6k-e592cf83b7","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Combining these strengths means greater access to flexible payment options for Grab's ecosystem of nearly 54 million Monthly Transacting Users, and more cross-sell opportunities for Grab into Atome Financial’s network of over 30,000 brands. 2.Enhancing credit capabilities to drive scale: The proposed acquisition mutually strengthens the companies’ credit underwriting capabilities. Pairing Atome Financial’s AI-powered lending infrastructure with Grab’s ecosystem insights could significantly enhance Grab’s credit risk underwriting capabilities, allowing Grab to expand product accessibility, while helping to prevent consumer over-indebtedness. Atome Financial’s $1 billion gross loan portfolio4 has maintained disciplined credit quality, with delinquency rates improving or stable across borrower cohorts.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001855612-26-000138"],"forms":{"6-K":1},"first":"2026-09-15","last":"2026-09-15","end":null}]});
